Q: Use printf to format floats without decimal places if only trailing 0s A: <p>From our discussion in <a href="https://stackoverflow.com/questions/9628645/use-printf-to-format-floats-without-decimal-places-if-only-trailing-0s/9628723#9628723">mechanical_meat's answer</a>, here is my program that works for any number of digits before the decimal.</p>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

int main() {
    float f1 = 12.13;
    float f2 = 12.245;
    float f3 = 1242.145;
    float f4 = 1214.1;

    int i = 0;
    char *s1 = (char *)(malloc(sizeof(char) * 20));
    char *s2 = (char *)(malloc(sizeof(char) * 20));

    sprintf(s1, &quot;%f&quot;, f1);
    s2 = strchr(s1, '.');
    i = s2 - s1;
    printf(&quot;%.*g\n&quot;, (i+2), f1);

    sprintf(s1, &quot;%f&quot;, f2);
    s2 = strchr(s1, '.');
    i = s2 - s1;
    printf(&quot;%.*g\n&quot;, (i+2), f2);

    sprintf(s1, &quot;%f&quot;, f3);
    s2 = strchr(s1, '.');
    i = s2 - s1;
    printf(&quot;%.*g\n&quot;, (i+2), f3);

    sprintf(s1, &quot;%f&quot;, f4);
    s2 = strchr(s1, '.');
    i = s2 - s1;
    printf(&quot;%.*g\n&quot;, (i+2), f4);

    free(s1);
    free(s2);

    return 0;
}
</code></pre>
<p>And here's the output:</p>
<pre class="lang-none prettyprint-override"><code>12.13
12.24
1242.15
1214.1
</code></pre>

Q: How to turn on front flash light programmatically in Android? A: <p>Complete Code for android Flashlight App</p>
<p>Manifest</p>
<pre><code>  &lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot;?&gt;
  &lt;manifest xmlns:android=&quot;http://schemas.android.com/apk/res/android&quot;
      package=&quot;com.user.flashlight&quot;
      android:versionCode=&quot;1&quot;
      android:versionName=&quot;1.0&quot;&gt;

      &lt;uses-sdk
          android:minSdkVersion=&quot;8&quot;
          android:targetSdkVersion=&quot;17&quot;/&gt;

      &lt;uses-permission android:name=&quot;android.permission.CAMERA&quot; /&gt;
      &lt;uses-feature android:name=&quot;android.hardware.camera&quot;/&gt;

      &lt;application
          android:allowBackup=&quot;true&quot;
          android:icon=&quot;@mipmap/ic_launcher&quot;
          android:label=&quot;@string/app_name&quot;
          android:theme=&quot;@style/AppTheme&quot; &gt;
          &lt;activity
              android:name=&quot;.MainActivity&quot;
              android:label=&quot;@string/app_name&quot; &gt;
              &lt;intent-filter&gt;
                  &lt;action android:name=&quot;android.intent.action.MAIN&quot; /&gt;

                  &lt;category android:name=&quot;android.intent.category.LAUNCHER&quot; /&gt;
              &lt;/intent-filter&gt;
          &lt;/activity&gt;
      &lt;/application&gt;

  &lt;/manifest&gt;
</code></pre>
<p>XML</p>
<pre class="lang-xml prettyprint-override"><code>&lt;RelativeLayout xmlns:android=&quot;http://schemas.android.com/apk/res/android&quot;
    xmlns:tools=&quot;http://schemas.android.com/tools&quot; android:layout_width=&quot;match_parent&quot;
    android:layout_height=&quot;match_parent&quot; android:paddingLeft=&quot;@dimen/activity_horizontal_margin&quot;
    android:paddingRight=&quot;@dimen/activity_horizontal_margin&quot;
    android:paddingTop=&quot;@dimen/activity_vertical_margin&quot;
    android:paddingBottom=&quot;@dimen/activity_vertical_margin&quot; tools:context=&quot;.MainActivity&quot;&gt;

    &lt;Button
        android:layout_width=&quot;wrap_content&quot;
        android:layout_height=&quot;wrap_content&quot;
        android:text=&quot;OFF&quot;
        android:id=&quot;@+id/button&quot;
        android:layout_centerVertical=&quot;true&quot;
        android:layout_centerHorizontal=&quot;true&quot;
        android:onClick=&quot;turnFlashOnOrOff&quot; /&gt;
&lt;/RelativeLayout&gt;
</code></pre>
<p>MainActivity.java</p>
<pre><code>  import android.app.AlertDialog;
  import android.content.DialogInterface;
  import android.content.pm.PackageManager;
  import android.hardware.Camera;
  import android.hardware.Camera.Parameters;
  import android.support.v7.app.AppCompatActivity;
  import android.os.Bundle;
  import android.view.View;
  import android.widget.Button;

  import java.security.Policy;

  public class MainActivity extends AppCompatActivity {

      Button button;
      private Camera camera;
      private boolean isFlashOn;
      private boolean hasFlash;
      Parameters params;

      @Override
      protected void onCreate(Bundle savedInstanceState) {
          super.onCreate(savedInstanceState);
          setContentView(R.layout.activity_main);

          button = (Button) findViewById(R.id.button);

          hasFlash = getApplicationContext().getPackageManager().hasSystemFeature(PackageManager.FEATURE_CAMERA_FLASH);

          if(!hasFlash) {

              AlertDialog alert = new AlertDialog.Builder(MainActivity.this).create();
              alert.setTitle(&quot;Error&quot;);
              alert.setMessage(&quot;Sorry, your device doesn't support flash light!&quot;);
              alert.setButton(&quot;OK&quot;, new DialogInterface.OnClickListener() {
                  @Override
                  public void onClick(DialogInterface dialog, int which) {
                      finish();
                  }
              });
              alert.show();
              return;
          }

          getCamera();

          button.setOnClickListener(new View.OnClickListener() {
              @Override
              public void onClick(View v) {

                  if (isFlashOn) {
                      turnOffFlash();
                      button.setText(&quot;ON&quot;);
                  } else {
                      turnOnFlash();
                      button.setText(&quot;OFF&quot;);
                  }

              }
          });
      }

      private void getCamera() {

          if (camera == null) {
              try {
                  camera = Camera.open();
                  params = camera.getParameters();
              }catch (Exception e) {

              }
          }

      }

      private void turnOnFlash() {

          if(!isFlashOn) {
              if(camera == null || params == null) {
                  return;
              }

              params = camera.getParameters();
              params.setFlashMode(Parameters.FLASH_MODE_TORCH);
              camera.setParameters(params);
              camera.startPreview();
              isFlashOn = true;
          }

      }

      private void turnOffFlash() {

              if (isFlashOn) {
                  if (camera == null || params == null) {
                      return;
                  }

                  params = camera.getParameters();
                  params.setFlashMode(Parameters.FLASH_MODE_OFF);
                  camera.setParameters(params);
                  camera.stopPreview();
                  isFlashOn = false;
              }
      }

      @Override
      protected void onDestroy() {
          super.onDestroy();
      }

      @Override
      protected void onPause() {
          super.onPause();

          // on pause turn off the flash
          turnOffFlash();
      }

      @Override
      protected void onRestart() {
          super.onRestart();
      }

      @Override
      protected void onResume() {
          super.onResume();

          // on resume turn on the flash
          if(hasFlash)
              turnOnFlash();
      }

      @Override
      protected void onStart() {
          super.onStart();

          // on starting the app get the camera params
          getCamera();
      }

      @Override
      protected void onStop() {
          super.onStop();

          // on stop release the camera
          if (camera != null) {
              camera.release();
              camera = null;
          }
      }

  }
</code></pre>

Q: Retrieve secrets from AWS Secrets Manager in Node.js A: <p>To connect your AWS secret manager, you need to install the SDK ie. aws-sdk</p>
<pre><code>import { SecretsManager } from 'aws-sdk';
</code></pre>
<p>Code to fetch the secret values from the AWS secret manager.</p>
<pre><code>let SecretsManagerClient = new SecretsManager(
                           { region: 'YOUR_SECRET_MANAGER_REGION'});

const SecretsManagerResult = await SecretsManagerClient
                            .getSecretValue({
                                SecretId: 'YOUR_SECRET_MANAGER_KEY',
                             })
                            .promise();
</code></pre>
<p>SecretsManagerClient().getSecretValue() will return data so you need to parse this data as.</p>
<pre><code>const SecretsManagerResponse = JSON.parse(SecretsManagerResult.SecretString);
const {clsa_key, clsa_secret} = SecretsManagerResponse;
</code></pre>
<p>Thanks</p>

